      hu: "Thaiföld legnagyobb ipari parkja, amely a petrolkémiai és nehéziparra összpontosít, saját mélytengeri kikötővel.",
      ro: "Cel mai mare parc industrial din Thailanda, axat pe industria petrochimică și grea, cu propriul său port de mare adâncime.",
      en: "Thailand's largest industrial estate, focusing on the petrochemical and heavy industries, with its own deep-sea port.",
      es: "El parque industrial más grande de Tailandia, centrado en la petroquímica y la industria pesada, con su propio puerto de aguas profundas.",
      pt: "A maior zona industrial da Tailândia, centrada na petroquímica e na indústria pesada, com o seu próprio porto de águas profundas.",
