      hu: ["A műanyag- és vegyszergyártás fontos központja.", "Környezeti hatásokkal kapcsolatos aggályokat vetett fel.", "A thaiföldi gazdasági növekedés egyik fontos motorja."],
      ro: ["Un centru vital pentru producția de materiale plastice și produse chimice.", "A generat preocupări legate de impactul asupra mediului.", "Un motor cheie al creșterii economice a Thailandei."],
      en: ["A vital center for plastics and chemical production.", "Has raised environmental impact concerns.", "A key driver of Thailand's economic growth."],
      es: ["Centro importante para la producción de plásticos y productos químicos.", "Ha suscitado preocupación por el impacto medioambiental.", "Un motor importante del crecimiento económico de Tailandia."],
