      hu: ["Nagy számú bengáli tigriséről ismert.", "Voltak programjai, ahol tigriskölykök és malacok nevelték egymást.", "Állatjóléti aggályok miatt kritizálták."],
      ro: ["Cunoscut pentru numărul mare de tigri bengalezi.", "Avea programe în care puii de tigru și purceii erau crescuți împreună.", "A fost criticat pentru probleme legate de bunăstarea animalelor."],
      en: ["Known for its large number of Bengal tigers.", "Featured programs of tiger cubs and piglets being raised together.", "Faced criticism over animal welfare concerns."],
