      es: "Un gran puerto marítimo en el río Chao Phraya, que históricamente fue el puerto internacional más importante de Tailandia antes de la construcción de Laem Chabang.",
      pt: "Um grande porto marítimo no rio Chao Phraya, que historicamente foi o porto internacional mais importante da Tailândia antes da construção de Laem Chabang.",
