      hu: ["Khlong Toei kikötőként is ismert.", "Központi helyen fekszik Bangkokban, ami közlekedési problémákat okoz.", "Ma főként darabárut és part menti kereskedelmet bonyolít le."],
      ro: ["Cunoscut și sub numele de Portul Khlong Toei.", "Situat central în Bangkok, ceea ce duce la congestionarea traficului.", "Acum se ocupă în principal de mărfuri generale și comerț costier."],
