      hu: "Hatalmas terület a Thai-öbölben, számos tengeri földgázmezővel, amelyek Thaiföld energiaellátásának gerincét alkotják.",
      ro: "O zonă vastă în Golful Thailandei cu numeroase câmpuri de gaze naturale offshore, care constituie coloana vertebrală a aprovizionării cu energie a Thailandei.",
      en: "A vast area in the Gulf of Thailand containing numerous offshore natural gas fields that form the backbone of Thailand's energy supply.",
      es: "Una vasta área en el Golfo de Tailandia con numerosos yacimientos de gas natural en alta mar, que forman la columna vertebral del suministro energético de Tailandia.",
      pt: "Uma vasta área no Golfo da Tailândia com numerosos campos de gás natural ao largo da costa, que formam a espinha dorsal do abastecimento energético da Tailândia.",
      fr: "Une vaste zone dans le golfe de Thaïlande comportant de nombreux gisements de gaz naturel offshore, qui constituent l'épine dorsale de l'approvisionnement énergétique de la Thaïlande.",
