      ro: ["Câmpul de gaze Erawan este unul dintre cele mai mari.", "Gazul este transportat la uscat prin conducte către centralele electrice.", "Dezvoltarea a început în anii 1970.", "Un contributor major la PIB-ul Thailandei."],
