      de: ["Bedeckt eine riesige Fläche mit Photovoltaik-Paneelen.", "Liefert saubere Energie in das nationale Netz.", "Ein Beispiel für Thailands Potenzial in der Solarenergie.", "Reduziert die Abhängigkeit von fossilen Brennstoffen."],
      hu: ["Hatalmas területet borítanak fotovoltaikus panelek.", "Tiszta energiát szolgáltat a nemzeti hálózatba.", "Példa Thaiföld napenergia-potenciáljára.", "Csökkenti a fosszilis tüzelőanyagoktól való függőséget."],
      ro: ["Acoperă o suprafață vastă cu panouri fotovoltaice.", "Furnizează energie curată rețelei naționale.", "Un exemplu al potențialului solar al Thailandei.", "Reduce dependența de combustibilii fosili."],
      en: ["Covers a vast area with photovoltaic panels.", "Supplies clean energy to the national grid.", "An example of Thailand's solar power potential.", "Reduces reliance on fossil fuels."],
