      en: ["One of the world's leading trade shows for the gem and jewelry industry, held twice a year, highlighting Thailand's role as a global trading hub.", "Located within the Kingdom of Thailand.", "Shaped by the monsoon climate of Southeast Asia.", "Linked to the heritage of the Sukhothai and Ayutthaya kingdoms."],
      es: ["Una de las ferias comerciales líderes del mundo para la industria de gemas y joyería, celebrada dos veces al año, que subraya el papel de Tailandia como centro comercial global.", "Situada en el territorio del Reino de Tailandia.", "Marcada por el clima monzónico del sudeste asiático.", "Vinculada al legado de Sukhothai y Ayutthaya."],
      pt: ["Uma das feiras comerciais líderes do mundo para a indústria de gemas e joalharia, realizada duas vezes por ano, sublinhando o papel da Tailândia como um centro comercial global.", "Situada no território do Reino da Tailândia.", "Marcada pelo clima de monção do sudeste asiático.", "Vinculada ao legado de Sukhothai e Ayutthaya."],
      fr: ["L'un des principaux salons commerciaux mondiaux pour l'industrie des pierres précieuses et de la bijouterie, organisé deux fois par an, soulignant le rôle de la Thaïlande en tant que centre commercial mondial.", "Située sur le territoire du Royaume de Thaïlande.", "Marquée par le climat de mousson de l'Asie du Sud-Est.", "Liée à l'héritage de Sukhothai et Ayutthaya."],
